SET DEFINE OFF;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
WHENEVER OSERROR EXIT FAILURE ROLLBACK;
ALTER SESSION SET NLS_LANGUAGE = 'SPANISH';
ALTER SESSION SET NLS_TERRITORY = 'SPAIN';

-- =============================================================================
-- Nivel 1: CATÁLOGOS BASE (ROLES, MÓDULOS Y ESTADOS DE CITA)
-- =============================================================================

MERGE INTO ROLES target
USING (
    SELECT '99999999-9999-9999-9999-999999999999' AS ID, 'SuperAdmin' AS NAME, 'Control total' AS DESCRIPTION FROM DUAL UNION ALL
    SELECT '11111111-1111-1111-1111-111111111111' AS ID, 'Administrador' AS NAME, 'Configura el sistema' AS DESCRIPTION FROM DUAL UNION ALL
    SELECT '44444444-4444-4444-4444-444444444444' AS ID, 'Veterinario' AS NAME, 'Atiende citas' AS DESCRIPTION FROM DUAL UNION ALL
    SELECT '55555555-5555-5555-5555-555555555555' AS ID, 'Recepcionista' AS NAME, 'Gestiona agenda' AS DESCRIPTION FROM DUAL UNION ALL
    SELECT '66666666-6666-6666-6666-666666666666' AS ID, 'Auxiliar' AS NAME, 'Apoya atención' AS DESCRIPTION FROM DUAL UNION ALL
    SELECT '77777777-7777-7777-7777-777777777777' AS ID, 'Cliente' AS NAME, 'Dueño de mascota' AS DESCRIPTION FROM DUAL
) source ON (UPPER(target.NAME) = UPPER(source.NAME))
WHEN MATCHED THEN UPDATE SET target.ROLE_ID = source.ID, target.DESCRIPTION = source.DESCRIPTION
WHEN NOT MATCHED THEN INSERT (ROLE_ID, NAME, DESCRIPTION, CREATED_AT) VALUES (source.ID, source.NAME, source.DESCRIPTION, SYSTIMESTAMP);

